"use client";

import React from "react";
import { Navigation } from "@/components/Navigation";
import { PageBackground } from "@/components/PageBackground";
import { BackLink } from "@/components/BackLink";
import { ScrollReveal } from "@/components/ScrollReveal";

/* ─── Tier data ─── */
const tiers = [
    {
        id: "sources",
        label: "01",
        title: "Data Sources",
        desc: "Application logs, infrastructure metrics, distributed traces, deployment events, and configuration state changes stream continuously from your production environment.",
        align: "left" as const,
    },
    {
        id: "ingestion",
        label: "02",
        title: "Ingestion & Streaming",
        desc: "High-throughput ingestion pipeline normalizes, enriches, and routes signals through a real-time streaming mesh. Schema-aware parsing ensures consistency across heterogeneous telemetry formats.",
        align: "right" as const,
    },
    {
        id: "reasoning",
        label: "03",
        title: "Reasoning & Correlation",
        desc: "LLM-powered reasoning engine performs multi-hop causal inference across correlated signal clusters. Temporal pattern matching and topological analysis isolate root causes within milliseconds.",
        align: "left" as const,
    },
    {
        id: "execution",
        label: "04",
        title: "Execution & Control",
        desc: "Validated remediation plans dispatch through an execution gateway with configurable approval policies. Infrastructure-as-code operations execute atomically with automatic rollback safety nets.",
        align: "right" as const,
    },
    {
        id: "feedback",
        label: "05",
        title: "Feedback & Observability Loop",
        desc: "Post-action effectiveness is measured against baseline SLIs. Outcomes feed back into the reasoning model, continuously improving accuracy and reducing false-positive rates over time.",
        align: "left" as const,
    },
];

export default function ArchitecturePage() {
    return (
        <div className="relative w-full min-h-screen text-white overflow-x-hidden">
            <PageBackground />
            <Navigation />
            <BackLink />

            {/* ─── Hero ─── */}
            <ScrollReveal className="relative z-10 pt-12 pb-20 px-8">
                <div className="max-w-5xl mx-auto text-center">
                    <h1 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-gradient mb-6 drop-shadow-2xl">
                        Architecture
                    </h1>
                    <p className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto tracking-wide font-medium">
                        Five-tier autonomous reliability pipeline — from raw signal to closed-loop healing
                    </p>
                </div>
            </ScrollReveal>

            {/* ═══════════════════════════════════════════════
                SYSTEM FLOW — Five-tier vertical stack
            ═══════════════════════════════════════════════ */}
            <div className="relative z-10 px-8 mb-24">
                <div className="max-w-6xl mx-auto relative">

                    {/* Vertical flow connector line */}
                    <div
                        className="absolute left-1/2 top-0 bottom-0 w-px -translate-x-1/2 hidden lg:block"
                        style={{
                            background: "linear-gradient(180deg, rgba(224,176,255,0.0) 0%, rgba(224,176,255,0.12) 10%, rgba(224,176,255,0.08) 50%, rgba(224,176,255,0.12) 90%, rgba(224,176,255,0.0) 100%)",
                        }}
                    />

                    {tiers.map((tier, index) => {
                        const isLeft = tier.align === "left";
                        /* Vary spacing between tiers for hierarchy */
                        const marginBottom = index === 0 ? "mb-16" : index === 2 ? "mb-20" : index === 4 ? "mb-0" : "mb-14";

                        return (
                            <ScrollReveal
                                key={tier.id}
                                delay={index * 0.08}
                                className={`relative ${marginBottom}`}
                            >
                                {/* Flow node dot on center line */}
                                <div className="absolute left-1/2 top-8 -translate-x-1/2 hidden lg:flex flex-col items-center">
                                    <div
                                        className="w-3 h-3 rounded-full border-2"
                                        style={{
                                            borderColor: "rgba(224,176,255,0.3)",
                                            background: index === 2
                                                ? "rgba(224,176,255,0.5)"
                                                : "rgba(224,176,255,0.15)",
                                            boxShadow: index === 2
                                                ? "0 0 12px rgba(224,176,255,0.3)"
                                                : "none",
                                        }}
                                    />
                                    {/* Direction arrow */}
                                    {index < tiers.length - 1 && (
                                        <div className="mt-1 text-[#E0B0FF]/20 text-xs">▼</div>
                                    )}
                                </div>

                                {/* Tier surface band */}
                                <div
                                    className={`w-full lg:w-[55%] rounded-[2rem] p-10 lg:p-14 relative overflow-hidden ${isLeft ? "lg:mr-auto" : "lg:ml-auto"}`}
                                    style={{
                                        background: `linear-gradient(${isLeft ? "145deg" : "215deg"}, rgba(74,14,96,${0.05 + index * 0.015}) 0%, rgba(15,17,23,${0.4 + index * 0.05}) 60%, rgba(5,5,5,0.3) 100%)`,
                                        backdropFilter: "blur(12px)",
                                    }}
                                >
                                    {/* Top edge glow */}
                                    <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/10 to-transparent" />

                                    {/* Background depth orb */}
                                    <div
                                        className="absolute rounded-full"
                                        style={{
                                            width: "200px",
                                            height: "200px",
                                            top: isLeft ? "-40px" : "auto",
                                            bottom: isLeft ? "auto" : "-40px",
                                            right: isLeft ? "-30px" : "auto",
                                            left: isLeft ? "auto" : "-30px",
                                            background: `radial-gradient(circle, rgba(224,176,255,${0.03 + index * 0.01}) 0%, transparent 70%)`,
                                            filter: "blur(30px)",
                                        }}
                                    />

                                    <div className="relative z-10">
                                        <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/50 mb-4">
                                            {tier.label} — Tier
                                        </div>
                                        <h3 className="text-2xl md:text-3xl font-bold tracking-tight text-white mb-4">
                                            {tier.title}
                                        </h3>
                                        <p className="text-gray-400 leading-relaxed max-w-lg">
                                            {tier.desc}
                                        </p>
                                    </div>

                                    {/* Bottom edge */}
                                    <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/3 to-transparent" />
                                </div>
                            </ScrollReveal>
                        );
                    })}
                </div>
            </div>

            {/* ═══════════════════════════════════════════════
                SUPPLEMENTAL — Bento-style architecture summary
            ═══════════════════════════════════════════════ */}
            <ScrollReveal delay={0.15} className="relative z-10 px-8 mb-32">
                <div className="max-w-7xl mx-auto">
                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/60 mb-6 px-2">System Overview</div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                        {/* Large overview block — 8 columns */}
                        <div
                            className="lg:col-span-8 rounded-[2rem] p-12 lg:p-14 min-h-[350px] flex flex-col justify-between relative overflow-hidden"
                            style={{
                                background: "linear-gradient(155deg, rgba(74,14,96,0.08) 0%, rgba(15,17,23,0.55) 50%, rgba(5,5,5,0.35) 100%)",
                                backdropFilter: "blur(16px)",
                            }}
                        >
                            <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/15 to-transparent" />
                            <div className="absolute -bottom-20 -right-20 w-80 h-80 rounded-full"
                                style={{ background: "radial-gradient(circle, rgba(74,14,96,0.06) 0%, transparent 70%)" }}
                            />

                            <div className="relative z-10">
                                <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15]">
                                    Closed-Loop<br />
                                    <span className="text-gray-500">Reliability Engine</span>
                                </h2>
                                <p className="text-gray-400 leading-relaxed max-w-xl">
                                    AEGIS operates as a continuous feedback system. Every remediation
                                    outcome refines the reasoning model. Anomaly baselines adapt to
                                    infrastructure drift. The platform becomes more precise with every
                                    incident it processes — converging toward zero human intervention
                                    for known failure modes.
                                </p>
                            </div>

                            <div className="relative z-10 flex gap-10 mt-8 text-sm font-mono">
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">5</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Processing Tiers</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">∞</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Feedback Loops</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">&lt;12s</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">End-to-End Cycle</div>
                                </div>
                            </div>
                        </div>

                        {/* Two smaller blocks stacked — 4 columns, asymmetrical heights */}
                        <div className="lg:col-span-4 flex flex-col gap-6">
                            <div
                                className="rounded-[2rem] p-10 flex-[1.4] flex flex-col justify-center relative overflow-hidden"
                                style={{
                                    background: "linear-gradient(140deg, rgba(224,176,255,0.04) 0%, rgba(15,17,23,0.5) 100%)",
                                    backdropFilter: "blur(12px)",
                                }}
                            >
                                <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/10 to-transparent" />
                                <h3 className="text-xl font-bold text-white mb-3">Extensible Pipeline</h3>
                                <p className="text-gray-400 text-sm leading-relaxed">
                                    Every tier exposes plugin interfaces — custom anomaly
                                    detectors, bespoke reasoning modules, and organization-specific
                                    remediation playbooks integrate seamlessly.
                                </p>
                            </div>

                            <div
                                className="rounded-[2rem] p-10 flex-[0.6] flex flex-col justify-center relative overflow-hidden"
                                style={{
                                    background: "linear-gradient(175deg, rgba(74,14,96,0.06) 0%, rgba(10,12,16,0.5) 100%)",
                                    backdropFilter: "blur(12px)",
                                }}
                            >
                                <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />
                                <h3 className="text-xl font-bold text-white mb-3">Zero-Trust Execution</h3>
                                <p className="text-gray-400 text-sm leading-relaxed">
                                    All remediation actions traverse an audit gateway with
                                    cryptographic provenance and approval chain verification.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </ScrollReveal>

            {/* Bottom spacer */}
            <div className="relative z-10 h-32" />
        </div>
    );
}
